ON CONFLICT(tpl_id) DO UPDATE SET name = excluded.name, category = excluded.category, caps_json = excluded.caps_json, instance_params_json = excluded.instance_params_json, sync_json = excluded.sync_json, async_json = excluded.async_json, upload_json = excluded.upload_json, clone_json = excluded.clone_json, ord = excluded.ord;
